/* Function Objective: Find the largest value in a list
   Input parameters : f_value_list (float array) the values, f_value_total (integer) number of values
   Function description: Start from the first value and keep the largest value seen while walking through the list
   Return Value : float largest value
   Created By : Programmer A
   Create Date: 2026-09-28
   Revised By:
   Revised Date:
*/
float f_Find_Maximum(const float f_value_list[], int i_value_total) {
    float f_maximum = f_value_list[0];
    // check every value after the first one
    for (int index = 1; index < i_value_total; index++) {
        // check whether the value is larger than the current maximum
        if (f_value_list[index] > f_maximum) {
            f_maximum = f_value_list[index];
        }
        // else the value is not larger, keep the maximum
        else {
            f_maximum = f_maximum + 0.0f;
        }
    }
    return f_maximum;
}
